package audit

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"go.flipt.io/flipt/rpc/flipt"
)

func TestFlag(t *testing.T) {
	f := &flipt.Flag{
		Key:            "flipt",
		Name:           "flipt",
		NamespaceKey:   "flipt",
		Enabled:        false,
		DefaultVariant: nil,
	}
	nf := NewFlag(f)

	assert.Equal(t, nf.Enabled, f.Enabled)
	assert.Equal(t, nf.Key, f.Key)
	assert.Equal(t, nf.Name, f.Name)
	assert.Equal(t, nf.NamespaceKey, f.NamespaceKey)
}

func TestFlagWithDefaultVariant(t *testing.T) {
	f := &flipt.Flag{
		Key:          "flipt",
		Name:         "flipt",
		NamespaceKey: "flipt",
		Enabled:      false,
		DefaultVariant: &flipt.Variant{
			Key: "default-variant",
		},
	}
	nf := NewFlag(f)

	assert.Equal(t, nf.Enabled, f.Enabled)
	assert.Equal(t, nf.Key, f.Key)
	assert.Equal(t, nf.Name, f.Name)
	assert.Equal(t, nf.NamespaceKey, f.NamespaceKey)
	assert.Equal(t, "default-variant", nf.DefaultVariant)

}

func TestVariant(t *testing.T) {
	v := &flipt.Variant{
		Id:      "this-is-an-id",
		FlagKey: "flipt",
		Key:     "flipt",
		Name:    "flipt",
	}

